// Sets the demo IdP certificate generated by entrypoint.sh as the signing certificate of the
// SPID provider of the realm (Keycloak Admin REST API): Keycloak then accepts the demo IdP responses.
// Usage (from register.sh): node trust.js <certificate PEM file>
const fs = require('fs');

const keycloak = process.env.KEYCLOAK_URL || 'http://keycloak:8080';
const realm = process.env.IAM4D_REALM || 'iam4d-sample';
const alias = process.env.SPID_ALIAS || 'spid-test';
const certificate = fs.readFileSync(process.argv[2], 'utf8').replace(/-----[^-]+-----|\s/g, '');

async function call(url, options) {
  const response = await fetch(url, options);
  if (!response.ok)
    throw new Error(`${options?.method || 'GET'} ${url}: HTTP ${response.status}`);
  return response;
}

(async () => {
  const token = (await (await call(`${keycloak}/realms/master/protocol/openid-connect/token`, {
    method: 'POST',
    body: new URLSearchParams({
      grant_type: 'password', client_id: 'admin-cli',
      username: process.env.KC_ADMIN || 'admin', password: process.env.KC_ADMIN_PASSWORD || 'admin'
    })
  })).json()).access_token;
  const headers = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
  const url = `${keycloak}/admin/realms/${realm}/identity-provider/instances/${alias}`;
  const provider = await (await call(url, { headers })).json();
  provider.config.signingCertificate = certificate;
  await call(url, { method: 'PUT', headers, body: JSON.stringify(provider) });
  console.log(`Signing certificate of the demo IdP set on ${realm}/${alias}`);
})().catch(e => {
  console.error(e.message);
  process.exit(1);
});
